// Parse WTO timeseries API response
// WTO API returns: { Dataset: [...] } with fields like Year, Value, Indicator, etc.
const rawData = $input.item.json;
const rows = [];

try {
  let dataset = [];
  if (rawData.Dataset) {
    dataset = rawData.Dataset;
  } else if (Array.isArray(rawData)) {
    dataset = rawData;
  } else if (rawData.value) {
    dataset = rawData.value;
  }

  if (dataset.length > 0) {
    // Group by indicator, get latest year WITH actual non-null data
    const indicatorMap = {};
    for (const item of dataset) {
      const rawValue = item.Value !== undefined ? item.Value : item.value;
      // Skip null/undefined values
      if (rawValue === null || rawValue === undefined || rawValue === '') continue;

      const value = parseFloat(rawValue);
      if (isNaN(value)) continue;

      const indicatorName = item.Indicator || item.IndicatorCategory || item.ProductOrSector || 'Agricultural Products';
      const year = String(item.Year || item.Period || 'unknown');
      const key = indicatorName;

      // Only replace if this year is newer than what we have
      if (!indicatorMap[key] || year > indicatorMap[key].year) {
        indicatorMap[key] = { year, value, indicatorName };
      }
    }

    for (const [key, data] of Object.entries(indicatorMap)) {
      rows.push({
        source: 'WTO',
        commodity: 'Agricultural Products (VN)',
        metric: 'avg_mfn_import_tariff',
        value: data.value,
        unit: '%',
        period: data.year
      });
    }
  }
} catch (e) {
  // fallback on error
}

if (rows.length === 0) {
  rows.push({
    source: 'WTO',
    commodity: 'Agricultural Products (VN)',
    metric: 'avg_mfn_import_tariff',
    value: 0,
    unit: '%',
    period: 'no_data'
  });
}

return rows.map(r => ({ json: r }));
